// Derived from hdl-util/hdmi, Sameer Puri; MIT license: third_party/hdl_util_hdmi/LICENSE-MIT.
// Candidate: preserve the accepted-pixel to next-edge output latency and CE hold.
// Two synchronous ROMs replace stage1 binary encoding and nonvideo selection.
// Packed video word also carries its popcount, shortening stage2 arithmetic.
`timescale 1ns/1ps
module hu_tmds_channel_pipelined #(parameter signed [31:0] CN=0)(
 input wire clk_pixel,pixel_ce,input wire [7:0] video_data,
 input wire [3:0] data_island_data,input wire [1:0] control_data,
 input wire [2:0] mode,output reg [9:0] tmds=10'b1101010100
);
 reg signed [3:0] acc_half=0;reg ce_d=0,video_mode_d=0;
 (*rom_style="bram",force_ram*) reg [12:0] video_rom[0:255];
 (*rom_style="bram",force_ram*) reg [9:0] nonvideo_rom[0:511];
 reg [12:0] video_word;reg [9:0] nonvideo_d;integer init;
 localparam [3327:0] VIDEO_BITS=3328';
 localparam [5119:0] NONVIDEO_BITS=CN==0?5120':
  CN==1?5120':CN==2?5120':5120';
 initial begin
  for(init=0;init<256;init=init+1)video_rom[init]=VIDEO_BITS[init*13+:13];
  for(init=0;init<512;init=init+1)nonvideo_rom[init]=NONVIDEO_BITS[init*10+:10];
 end
 // ROM output registers require no initial/reset value: ce_d starts0 and
 // cannot consume a ROM word until after its first enabled read.
 always @(posedge clk_pixel)if(pixel_ce)begin
  video_word<=video_rom[video_data];
  nonvideo_d<=nonvideo_rom[{mode,data_island_data,control_data}];
 end
 always @(posedge clk_pixel)begin ce_d<=pixel_ce;if(pixel_ce)video_mode_d<=mode==1;end
 wire [8:0] q_m=video_word[8:0];wire [3:0] ones_q=video_word[12:9];
 wire signed [3:0] balance=ones_q-4'd4;
 wire neutral=(acc_half==0)||(ones_q==4);
 wire same_sign=acc_half[3]?(ones_q<4):(ones_q>4);
 wire invert=neutral?!q_m[8]:same_sign;
 wire [9:0] video_coding={invert,q_m[8],q_m[7:0]^{8{invert}}};
 reg signed [3:0] increment;
 always @*begin
  if(neutral)increment=invert?-balance:balance;
  else if(same_sign)increment=-balance+(q_m[8]?4'sd1:4'sd0);
  else increment=balance-(q_m[8]?4'sd0:4'sd1);
 end
 always @(posedge clk_pixel)if(ce_d)begin
  acc_half<=!video_mode_d?4'sd0:acc_half+increment;
  tmds<=video_mode_d?video_coding:nonvideo_d;
 end
endmodule
